'use strict';

// MODULES //

var remark = require( 'remark' );
var format = require( '@stdlib/string/format' );
var canonical = require( './canonical.js' );


// VARIABLES //

var compiler = remark().data( 'settings', {
	'bullet': '-',
	'fences': true
});


// FUNCTIONS //

/**
* Returns an exact semantic source slice when every source ref provides one.
*
* @private
* @param {Object} node - semantic node
* @returns {(string|null)} source slice
*/
function sourceSlice( node ) { // FIXME: move to separate module and remove method export below
	var refs = node.source.refs;
	var out = '';
	var i;

	if ( refs.length === 0 ) {
		return null;
	}
	for ( i = 0; i < refs.length; i++ ) {
		if ( typeof refs[ i ].value !== 'string' ) {
			return null;
		}
		out += refs[ i ].value;
	}
	return out;
}

/**
* Returns a rendered failure.
*
* @private
* @param {string} code - code
* @param {string} message - message
* @returns {Object} result
*/
function failure( code, message ) {
	return {
		'ok': false,
		'code': code,
		'message': message
	};
}

/**
* Returns a root MDAST for a semantic node.
*
* @private
* @param {Object} node - semantic node
* @param {Object} definitions - definition resources by ID
* @returns {Object} root MDAST
*/
function tree( node, definitions ) {
	var title;
	var url;

	if ( node.type === 'heading' ) {
		return {
			'type': 'root',
			'children': [
				{
					'type': 'heading',
					'depth': node.depth,
					'children': node.ast.children
				}
			]
		};
	}
	if ( node.type === 'summary' ) {
		return {
			'type': 'root',
			'children': [
				{
					'type': 'blockquote',
					'children': node.ast.children
				}
			]
		};
	}
	if ( node.type === 'markdown' ) {
		return node.ast;
	}
	if ( node.type === 'code' ) {
		return {
			'type': 'root',
			'children': [
				{
					'type': 'code',
					'lang': node.lang || node.language,
					'meta': node.meta,
					'value': node.value
				}
			]
		};
	}
	if ( node.type === 'frontmatter' ) {
		return {
			'type': 'root',
			'children': [
				{
					'type': 'code',
					'lang': node.format,
					'meta': null,
					'value': node.value
				}
			]
		};
	}
	if ( node.type === 'media' ) {
		url = node.renderedUrl || node.authoredUrl;
		if ( !url ) {
			return null;
		}
		title = null;
		if ( node.definitionRef && definitions[ node.definitionRef ] ) {
			title = definitions[ node.definitionRef ].title;
		}
		return {
			'type': 'root',
			'children': [
				{
					'type': 'paragraph',
					'children': [
						{
							'type': 'image',
							'url': url,
							'alt': node.alt,
							'title': title
						}
					]
				}
			]
		};
	}
	if ( node.type === 'thematicBreak' ) {
		return {
			'type': 'root',
			'children': [
				{
					'type': 'thematicBreak'
				}
			]
		};
	}
	return null;
}


// MAIN //

/**
* Renders one semantic node as Markdown.
*
* @param {Object} node - semantic node
* @param {Object} definitions - definition resources by ID
* @returns {Object} rendering result
*/
function render( node, definitions ) {
	var slice;
	var ast;
	var out;

	if ( node.type === 'math' ) {
		return {
			'ok': true,
			'value': '$$\n'+node.value.replace( /\r\n?/g, '\n' )+'\n$$\n'
		};
	}
	if ( node.type === 'raw' && node.format === 'html' ) {
		return {
			'ok': true,
			'value': node.value
		};
	}
	if ( node.type === 'media' ) {
		slice = sourceSlice( node );
		if ( slice !== null ) {
			return {
				'ok': true,
				'value': slice
			};
		}
		return failure( 'unrenderable-media', 'Media node does not retain an exact source slice needed for lossless rendering.' );
	}
	ast = tree( node, definitions );
	if ( !ast ) {
		return failure( 'unsupported-semantic-node', 'Semantic node cannot be represented as Markdown.' );
	}
	try {
		// The installed compiler may merge adjacent text nodes while stringifying. Compile a fresh tree so conversion never mutates the semantic document...
		out = compiler.stringify( canonical( ast ) );
	} catch ( err ) {
		return failure( 'unsupported-markdown-ast', format( 'Portable MDAST could not be rendered: %s', err.message ) );
	}
	return {
		'ok': true,
		'value': out
	};
}


// EXPORTS //

render.sourceSlice = sourceSlice;
module.exports = render;
